import mysql, {
  Pool,
  PoolConnection,
  ResultSetHeader,
  RowDataPacket,
} from 'mysql2/promise';
import 'dotenv/config';

//Represent row returned from the DB
export type DatabaseRow = Record<string, unknown>;

/**
 * result that gets returned by the DB
 *
 * rows     ==> data returned bu select queries
 * rowCount ==> number of affected rows
 * insertId ==> ID generated by insert query if available
 */

export interface DatabaseQueryResult<T = DatabaseRow> {
  rows: T[];
  rowCount: number;
  insertId?: number;
}

/**
 * for later
 */
export interface DatabaseClient {
  query<T = DatabaseRow>(
    text: string,
    params?: readonly unknown[],
  ): Promise<DatabaseQueryResult<T>>;
}

//require pool or connetion to use the execute() method
type QueryExecutor = Pick<Pool | PoolConnection, 'execute'>;

//Building the MySql connection from ENV
function databaseConfig() {
  const connectionString =
    process.env.DATABASE_URL ||
    'mysql://immoove-admin:Immoove_dev_root_password@localhost:3306/ImmooveDB';
  const url = new URL(connectionString);

  //Accept only MySql conn URLs
  if (url.protocol !== 'mysql:') {
    throw new Error('DATABASE_URL must use mysql://');
  }

  //Number of database conn allowed at same time
  const connectionLimit = Number.parseInt(process.env.DB_POOL_SIZE || '10', 10);

  return {
    host: url.hostname,
    port: url.port ? Number.parseInt(url.port, 10) : 3306,
    user: decodeURIComponent(url.username),
    password: decodeURIComponent(url.password),
    database: decodeURIComponent(url.pathname.replace(/^\//, '')),

    waitForConnections: true,

    connectionLimit:
      Number.isInteger(connectionLimit) && connectionLimit > 0
        ? connectionLimit
        : 10,

    //No limit on how may request that can wait for
    //an available conn
    queueLimit: 0,

    //Using UTC
    timezone: 'Z',
    charset: 'utf8mb4',

    //Only positional params
    namedPlaceholders: false,

    //Only one Sql Query is allowed to be excecuted a time
    multipleStatements: false,
    supportBigNumbers: true,
    bigNumberStrings: true,
    decimalNumbers: false,
  } as const;
}

/**
 * MySql Connection Pool
 * reusing  limited number of connections
 * instead of openning new one for each query
 */

export const pool = mysql.createPool(databaseConfig());

/**
 * Const for tracking the opened connections
 * WeakSet used to be garbage collected
 * when no longer used
 * */
const initializedConnections = new WeakSet<object>();



async function initializeConnection(connection: PoolConnection) {
  const physicalConnection =
    (connection as PoolConnection & { connection?: object }).connection ||
    connection;

  // Avoid running the initialization query multiple times on the
  // same physical connection.
  if (initializedConnections.has(physicalConnection)) return;

  // Force the MySQL session timezone to UTC.
  await connection.query("SET time_zone = '+00:00'");

  initializedConnections.add(physicalConnection);
}

/**
 * Execute a SQL query and normalize the result into our common
 */
async function execute<T>(
  executor: QueryExecutor,
  text: string,
  params: readonly unknown[] = [],
): Promise<DatabaseQueryResult<T>> {
  const [result] = await executor.execute(text, [...params] as any[]);

  if (Array.isArray(result)) {
    const rows = result as RowDataPacket[];

    //Catching the Tinyint columns with real boolean columns
    const booleanColumns = new Set([
      'is_active',
      'is_featured',
      'is_current',
      'requires_review',
      'requires_reacceptance',
      'is_published',
      'requires_terms_acceptance',
      'blocked',
      'has_review',
    ]);
    for (const row of rows) {
      for (const key of Object.keys(row)) {
        if (booleanColumns.has(key) && row[key] !== null)
          row[key] = Number(row[key]) !== 0;
      }
    }
    return { rows: rows as T[], rowCount: rows.length };
  }

  //INSERT, UPDATE and DELETE return metadata instead of rows
  const metadata = result as ResultSetHeader;
  return {
    rows: [],
    rowCount: metadata.affectedRows,
    //INSERT queries provide the generated auto-increment ID
    ...(metadata.insertId ? { insertId: metadata.insertId } : {}),
  };
}

/**
 * Execute a single database query.
 *
 * A connection is borrowed from the pool for the duration of the query
 * and always released afterward, even if the query fails.
 */

export async function query<T = DatabaseRow>(
  text: string,
  params: readonly unknown[] = [],
): Promise<DatabaseQueryResult<T>> {
  const connection = await pool.getConnection();
  try {
    await initializeConnection(connection);
    return await execute<T>(connection, text, params);
  } finally {
    //return the connection to the POOL
    connection.release();
  }
}

/**
 * Execute multiple database operations inside a transaction.
 *
 * If every operation succeeds, the transaction is committed.
 * If any operation fails, all changes are rolled back.
 */

export async function transaction<T>(
  fn: (client: DatabaseClient) => Promise<T>,
): Promise<T> {
  const connection = await pool.getConnection();

  /**
   * Expose only the database functionality needed by the transaction.
   * Services don't need direct access to the underlying connection.
   */

  const client: DatabaseClient = {
    query: <R = DatabaseRow>(text: string, params: readonly unknown[] = []) =>
      execute<R>(connection, text, params),
  };

  try {
    await initializeConnection(connection);

    //TO prevent a transaction from reading uncomitted changes made
    //by other transactions
    await connection.query('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');

    //Transaction Start
    await connection.beginTransaction();

    //Execute
    const result = await fn(client);

    //No Error, Apply the changes
    await connection.commit();
    return result;
  } catch (error) {
    try {  
      // Undo all changes made during the transaction.
      await connection.rollback();
    } catch {
      // If rollback itself fails, the connection may be in an unsafe state,
      // so destroy it instead of returning it to the pool.
      connection.destroy();
    }
    // Let the original error propagate to the caller.
    throw error;
  } finally {
    // Return the connection to the pool after the transaction finishes.
    connection.release();
  }
}
